Lemma ImplBlock_open : forall LB m b I,
  ImplBlock LB m b I ->
  exists p j7,
     In (p, b, 96) LB /\ rblock_range b 96
  /\ rw_cells rsegs m b (SpcHdrCells (im_hdr I) j7) /\ spc_ok (im_hdr I) /\ spc_vptr (im_hdr I) = VP_SPCI_IMPL
  /\ PMutex m (b + 32) (im_lk I)
  /\ rw_cells rsegs m (b + 72) [C8 (wz (im_vb I)); C8 (wz (im_vb I + 8 * zlength (im_states I))); C8 (wz (im_vb I + 8 * im_vcap I))]
  /\ zlength (im_states I) <= im_vcap I
  /\ ((im_vcap I = 0 /\ im_vb I = 0)
      \/ (exists q junk, In (q, im_vb I, 8 * im_vcap I) LB /\ rblock_range (im_vb I) (8 * im_vcap I) /\ 0 < im_vcap I
           /\ rw_cells rsegs m (im_vb I) [CB (8 * length (im_states I)) (flat_map le8z (im_states I));
                                         CB (Z.to_nat (8 * (im_vcap I - zlength (im_states I)))) junk])).
Proof.
  intros LB m b I (p & j7 & IN & RB & CH & OK & EV & PM & VC & LE & ST). exists p, j7.
  unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN in *.
  replace (b + 32 + 0) with (b + 32) in PM by lia. replace (b + 32 + 40) with (b + 72) in VC by lia.
  repeat (split; [fast_assumption|]). exact ST.
Qed.

Lemma ImplBlock_close : forall LB m b I p j7,
  In (p, b, 96) LB -> rblock_range b 96 ->
  rw_cells rsegs m b (SpcHdrCells (im_hdr I) j7) -> spc_ok (im_hdr I) -> spc_vptr (im_hdr I) = VP_SPCI_IMPL ->
  PMutex m (b + 32) (im_lk I) ->
  rw_cells rsegs m (b + 72) [C8 (wz (im_vb I)); C8 (wz (im_vb I + 8 * zlength (im_states I))); C8 (wz (im_vb I + 8 * im_vcap I))] ->
  zlength (im_states I) <= im_vcap I ->
  ((im_vcap I = 0 /\ im_vb I = 0)
      \/ (exists q junk, In (q, im_vb I, 8 * im_vcap I) LB /\ rblock_range (im_vb I) (8 * im_vcap I) /\ 0 < im_vcap I
           /\ rw_cells rsegs m (im_vb I) [CB (8 * length (im_states I)) (flat_map le8z (im_states I));
                                         CB (Z.to_nat (8 * (im_vcap I - zlength (im_states I)))) junk])) ->
  ImplBlock LB m b I.
Proof.
  intros LB m b I p j7 IN RB CH OK EV PM VC LE ST. exists p, j7.
  unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN.
  replace (b + 32 + 0) with (b + 32) by lia. replace (b + 32 + 40) with (b + 72) by lia.
  repeat (split; [fast_assumption|]). exact ST.
Qed.

