Definition SSVC_SHUTDOWN_STACK : Z := 176 + MTX_UNLOCK_STACK.

Definition ssvc_shutdown_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (v implb lo : Z) (S : svch) (I : implv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (implb + 32, implb + 72)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ StreamSvc LB m' v S implb
    /\ ImplBlock LB m' implb I.

Definition ssvc_shutdown_stmt : Prop :=
  forall (v implb lo : Z) (LB : list block) (S : svch) (I : implv)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  StreamSvc LB m v S implb -> 0 < v -> v mod 8 = 0 -> v + NEWSZ_SSVC <= hceil ->
  ImplBlock LB m implb I -> im_lk I = 0 -> im_states I = [] ->
  (v + NEWSZ_SSVC <= implb \/ implb + SZ_SPCI_IMPL <= v) ->
  (0 < im_vcap I -> im_vb I + 8 * im_vcap I <= implb \/ implb + SZ_SPCI_IMPL <= im_vb I) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + SSVC_SHUTDOWN_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (ssvc_shutdown_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB v implb lo S I m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SSVC_SHUTDOWN) fc None m (seg_rom rsegs)).
