(* [comment removed for export] *)

Definition STREAM_CLOSE_STACK : Z := 80 + MTX_UNLOCK_STACK.

(* [comment removed for export] *)
Definition cl_W (lo : Z) (sp : word) (bs stb : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (bs + 16, bs + 32); (stb + 104, stb + 144); (stb + 240, stb + 252)]%Z.

Definition stream_close_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (bs stb ioc implb lo : Z) (S : statev) (ds : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (cl_W lo sp bs stb) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' bs (BasicStreamCells stb)
    /\ StateBlock LB m' stb ioc implb (st_closed S) ds.

Definition stream_close_stmt : Prop :=
  forall (bs stb ioc implb lo : Z) (LB : list block) (S : statev) (ds : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  rw_cells rsegs m bs (BasicStreamCells stb) -> bs mod 8 = 0 -> bs + SZ_BS <= 2^64 ->
  (* [comment removed for export] *)
  StateBlock LB m stb ioc implb S ds -> st_lk S = 0 ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + STREAM_CLOSE_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= bs -> (bs + SZ_BS <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (stream_close_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB bs stb ioc implb lo S ds m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz bs) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STREAM_CLOSE) fc None m (seg_rom rsegs)).

