Definition STATE_REMOVE_STACK : Z := 48 + MTX_UNLOCK_STACK.

(* [comment removed for export] *)
Definition rm_W (lo : Z) (sp : word) (implb vb : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (implb + 8, implb + 12); (implb + 32, implb + 72); (implb + 80, implb + 88); (vb, vb + 8)]%Z.

