Definition impl_one (w i vb this vcap : Z) : implv := mkIMPL (mkSPC VP_SPCI_IMPL 1 w i) 0 vb [this] vcap.
Definition impl_none (w i vb vcap : Z) : implv := mkIMPL (mkSPC VP_SPCI_IMPL 1 w i) 0 vb [] vcap.

Definition state_remove_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (implb vb w i vcap lo : Z) (m : mem) : machine_state -> Prop :=
