Definition state_remove_stmt : Prop :=
  forall (stb implb vb w i vcap lo : Z) (LB : list block)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells rsegs m (stb + 88) [C8 (wz (implb + 32)); C8 (wz implb)] -> stb mod 16 = 0 -> stb + SZ_SPCI_STATE <= hceil ->
  (* [comment removed for export] *)
  ImplBlock LB m implb (impl_one w i vb (stb + 32) vcap) ->
  (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
  (stb + SZ_SPCI_STATE <= vb \/ vb + 8 * vcap <= stb) ->
  (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + STATE_REMOVE_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (state_remove_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB implb vb w i vcap lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (stb + 32)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
